class MarginsPage extends ConsumerWidget{
 const MarginsPage({super.key});
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Multiplayer Margins')),body:ListView(padding:const EdgeInsets.all(16),children:[
 const Text('Private until you select devices and explicitly transfer shared content. No automatic network, relay or background connection. Your private library is not a sync root.'),
 Wrap(spacing:8,children:[FilledButton.icon(onPressed:()async{final name=await marginPrompt(context,'New private workspace');if(name==null||!context.mounted){return;}String? id;final ok=await marginChange(context,ref,(r){id=(r.margins('create',name) as Map)['id'] as String;});if(ok&&context.mounted){context.push('/margins/workspace/$id');}},icon:const Icon(Icons.add),label:const Text('Create private workspace')),OutlinedButton(onPressed:()=>context.push('/margins/import'),child:const Text('Inspect / import encrypted package'))]),
 ref.watch(marginContactProvider).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(contact)=>ExpansionTile(title:Text('This device: ${contact.name}'),subtitle:const Text('Keys identify a device, not a verified person'),children:[SelectableText('Full signing fingerprint:\n${contact.key}'),TextButton(onPressed:()=>marginCode(context,'Public contact card',jsonEncode(contact.toJson())),child:const Text('Show / copy public contact card')),TextButton(onPressed:()async{final name=await marginPrompt(context,'Device display name',initial:contact.name);if(name!=null&&context.mounted){await marginChange(context,ref,(r)=>r.margins('set_name',name));}},child:const Text('Rename this device')),const ListTile(title:Text('Private keys remain in the local app database, not a hardware keystore. Device/database compromise is not covered; this protocol has not been independently audited.'))])),
 ref.watch(marginWorkspacesProvider).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(spaces)=>Column(children:[if(spaces.isEmpty)const ListTile(title:Text('No authenticated workspaces yet. Legacy prototype workspaces remain local and are not automatically promoted or sent.')),...spaces.map((w)=>Card(child:ListTile(title:Text(w.name),subtitle:Text('${w.role} · ${w.members.length} selected device(s) · ${w.enabled?'manual exchange enabled':'exchange paused'}\n${w.pendingTransfers} unacknowledged prepared transfer(s)'),onTap:()=>context.push('/margins/workspace/${w.id}'))))])),
 ]));
}
class MarginWorkspacePage extends ConsumerWidget{
 const MarginWorkspacePage({super.key,required this.id});final String id;
 @override Widget build(BuildContext context,WidgetRef ref)=>ref.watch(marginWorkspaceProvider(id)).when(loading:()=>Scaffold(appBar:AppBar(title:const Text('Workspace')),body:marginLoading()),error:(e,_)=>Scaffold(appBar:AppBar(title:const Text('Workspace')),body:marginError(e)),data:(w)=>DefaultTabController(length:4,child:Scaffold(appBar:AppBar(title:Text(w.name),bottom:const TabBar(isScrollable:true,tabs:[Tab(text:'Shared content'),Tab(text:'People & access'),Tab(text:'Exchange'),Tab(text:'History')])),body:TabBarView(children:[_Content(workspace:w),_People(workspace:w),MarginExchangePanel(workspace:w),_History(id:id)]))));
}
class _Content extends ConsumerStatefulWidget{const _Content({required this.workspace});final MarginWorkspace workspace;@override ConsumerState<_Content> createState()=>_ContentState();}
class _ContentState extends ConsumerState<_Content>{bool _deleted=false;String? _collection;@override Widget build(BuildContext context){final w=widget.workspace;final entries=w.entries.where((e)=>(_deleted||!e.deleted)&&(_collection==null||e.versions.any((v)=>v.collectionId==_collection))).toList();return ListView(padding:const EdgeInsets.all(16),children:[
 Text('Access: ${w.role}. Edits are saved offline, even while exchange is paused.'),const Text('All content placed here, including revision history and deleted versions, is included in future explicit state transfers. Private Reader annotations stay separate.'),
 if(w.canEdit)FilledButton.icon(onPressed:()=>context.push('/margins/new?workspace=${w.id}'),icon:const Icon(Icons.add_comment_outlined),label:const Text('Add shared content')),
 DropdownButtonFormField<String>(initialValue:_collection??'',decoration:const InputDecoration(labelText:'Research collection / reading list'),items:[const DropdownMenuItem(value:'',child:Text('All content')),...w.entries.where((e)=>!e.deleted&&e.versions.first.kind=='collection').map((e)=>DropdownMenuItem(value:e.id,child:Text(e.versions.first.title)))],onChanged:(v)=>setState(()=>_collection=v==''?null:v)),SwitchListTile(title:const Text('Include deleted entries (history is retained)'),value:_deleted,onChanged:(v)=>setState(()=>_deleted=v)),
 if(entries.isEmpty)const ListTile(title:Text('No shared content in this view. Originals are never added automatically.')),
 ...entries.map((e)=>_Entry(workspace:w,entry:e)),ExpansionTile(title:const Text('Privacy, limits & trust boundaries'),children:w.limitations.map((t)=>ListTile(title:Text(t))).toList()),
 ]);}}
class _Entry extends ConsumerWidget{
 const _Entry({required this.workspace,required this.entry});final MarginWorkspace workspace;final MarginEntry entry;
 Future<void> _bind(BuildContext context,WidgetRef ref,String document)async{try{final repo=await ref.read(bootstrapProvider.future);final items=repo.listItems(limit:100);if(!context.mounted){return;}final chosen=await showDialog<String>(context:context,builder:(ctx)=>SimpleDialog(title:const Text('Explicitly match a local source (first 100)'),children:items.map((i)=>SimpleDialogOption(onPressed:()=>Navigator.pop(ctx,i.id),child:Text(i.displayTitle))).toList()));if(chosen!=null&&context.mounted){await marginChange(context,ref,(r)=>r.margins('bind',{'id':workspace.id,'document_id':document,'item_id':chosen}));}}catch(e){if(context.mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}
 @override Widget build(BuildContext context,WidgetRef ref)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
 if(entry.conflict)const ListTile(leading:Icon(Icons.warning_amber),title:Text('Concurrent versions — explicit resolution required'),subtitle:Text('No edit or deletion was silently selected. Review every version before choosing.')),
 ...entry.versions.map((v)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${v.kind.toUpperCase()}${v.deleted?' · DELETED VERSION':''}${v.done?' · READ / DONE':''}',style:Theme.of(context).textTheme.labelLarge),Text(v.title,style:Theme.of(context).textTheme.titleMedium),SelectableText(v.body),if(v.replyTo!=null)Text('Reply to entry ${v.replyTo}'),if(v.collectionId!=null)Text('Collection ${v.collectionId}'),
 if(v.anchor!=null)...[const Text('Shared quotation — collaborator-supplied, not independent verification'),SelectableText(v.anchor!['quote'] as String),Text('Anchor: ${(entry.resolutions[v.id] as Map?)?['status']??'unbound'}'),Text((entry.resolutions[v.id] as Map?)?['explanation'] as String? ??'Match a local source to resolve this annotation.'),if(v.json['source_label']!=null)SelectableText('Shared source label: ${v.json['source_label']}'),if(v.json['source_url']!=null)SelectableText('Shared source URL: ${v.json['source_url']}'),TextButton(onPressed:()=>_bind(context,ref,v.anchor!['document_id'] as String),child:const Text('Match / change local source')),if((entry.resolutions[v.id] as Map?)?['block_idx']!=null&&(entry.resolutions[v.id] as Map?)?['local_item_id']!=null)TextButton(onPressed:()=>context.push('/reader/${Uri.encodeComponent((entry.resolutions[v.id] as Map)['local_item_id'] as String)}?block=${(entry.resolutions[v.id] as Map)['block_idx']}'),child:const Text('Open resolved supporting block'))],
 if(workspace.canEdit)Wrap(spacing:8,children:[TextButton(onPressed:()=>context.push('/margins/edit?workspace=${workspace.id}&entry=${entry.id}&revision=${v.id}'),child:Text(entry.conflict?'Review / resolve with this version':'Edit / mark read / delete')),TextButton(onPressed:()=>context.push('/margins/new?workspace=${workspace.id}&reply=${entry.id}'),child:const Text('Reply in thread'))]),const Divider(),
 ])),TextButton(onPressed:()=>context.push('/margins/thread?workspace=${workspace.id}&entry=${entry.id}'),child:const Text('Open discussion thread')),Text('${entry.historyCount} retained revision(s). Declared authors are peer-supplied; verified exporter keys appear in history.'),
 ])));
}
class _People extends ConsumerWidget{
 const _People({required this.workspace});final MarginWorkspace workspace;
 @override Widget build(BuildContext context,WidgetRef ref)=>ListView(padding:const EdgeInsets.all(16),children:[
 Text('My access: ${workspace.role} · owner policy epoch ${workspace.epoch}'),SelectableText('Owner fingerprint:\n${workspace.owner}'),const Text('Verify full device fingerprints using a trusted channel. A contact-card signature proves key possession, not a person’s identity. Editors may change all workspace content; viewers cannot publish edits.'),
 if(workspace.role=='owner')FilledButton(onPressed:()=>context.push('/margins/member?workspace=${workspace.id}'),child:const Text('Select device / change permissions')),
 ...workspace.members.map((m)=>ListTile(title:Text('${m.contact.name} · ${m.role}'),subtitle:SelectableText(m.contact.key))),
 const ListTile(title:Text('Revocation is learned only after a policy update reaches a device. It cannot erase past copies. After changing access, explicitly send policy updates to affected devices and state updates to continuing collaborators.')),
 ]);
}
class _History extends ConsumerWidget{
 const _History({required this.id});final String id;
 @override Widget build(BuildContext context,WidgetRef ref)=>ref.watch(marginHistoryProvider(id)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(h)=>ListView(padding:const EdgeInsets.all(16),children:[Text(h['attribution'] as String),const ListTile(title:Text('Latest 100 local exchange / policy events')),...marginRows(h,'events').map((e)=>ExpansionTile(title:Text('${e['kind']} · ${marginTime(e['recorded_ts'])}'),children:[SelectableText(e['detail'] as String)])),ExpansionTile(title:const Text('All retained logical revisions (max 512)'),children:marginRows(h,'revisions').map((r)=>ExpansionTile(title:Text('${r['title']} · ${r['deleted']==true?'deleted':'retained'}'),subtitle:Text('Peer-declared time ${marginTime(r['recorded_ts'])}; not verified event time'),children:[SelectableText(r['body'] as String),SelectableText('Declared author key (not verified): ${r['declared_author']}'),SelectableText('Revision ${r['id']}\nParents: ${(r['parents'] as List).join(', ')}')])).toList())]));
}

class MarginThreadPage extends ConsumerWidget{
 const MarginThreadPage({super.key,required this.workspaceId,required this.entryId});final String workspaceId,entryId;
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Document discussion thread')),body:ref.watch(marginWorkspaceProvider(workspaceId)).when(loading:marginLoading,error:(e,_)=>marginError(e),data:(w)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('Root entry and direct replies. Open a reply’s thread to follow nested discussions. Deleted and concurrent versions remain part of retained history.'),...w.entries.where((e)=>e.id==entryId||e.versions.any((v)=>v.replyTo==entryId)).map((e)=>_Entry(workspace:w,entry:e)),if(w.canEdit)FilledButton(onPressed:()=>context.push('/margins/new?workspace=$workspaceId&reply=$entryId'),child:const Text('Reply to this thread'))])));
}
